    {
      "id": 1,
      "claim": "In a depth‑first search of an undirected graph, every non‑tree edge connects a vertex to one of its ancestors in the DFS tree.",
      "evidence": "Property of DFS on undirected graphs: when an edge (x,y) is examined, if y is already visited then y must be an ancestor of x (or vice‑versa).",
      "weight": 0.4,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Given pre(u) < pre(v) for a non‑tree edge (u,v), u is an ancestor of v in T.",
      "evidence": "From step 1, the edge must join a vertex to an ancestor; the earlier‑visited endpoint (u) is the ancestor.",
      "weight": 0.3,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "If u is an ancestor of v, then the lowest common ancestor of u and v is u.",
      "evidence": "Definition of LCA: the deepest node that is ancestor of both; u itself satisfies this and no descendant of u can be ancestor of u.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "For an ancestor u and descendant v, postorder numbers satisfy post(v) < post(u).",
      "evidence": "In postorder, a node is recorded after all nodes in its subtree; thus descendants finish before the ancestor.",
      "weight": 0.1,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "Statement I (post(u) < post(v)) is false in this situation.",
      "evidence": "From step 4 we have post(v) < post(u), the opposite inequality.",
      "weight": 0.05,
      "depends_on": [4]
    }
  ],
  "considered": [
    {
      "answer": "A (I only)",
      "reason_rejected": "I is not guaranteed; it is actually false when u is ancestor of v."
    },
    {
      "answer": "B (II only)",
      "reason_rejected": "III also follows from the ancestor relationship."
    },
